Certainly! Below is an example of how you might implement a Contextual Multi-Armed Bandit (CMAB) algorithm using Object-Oriented Programming (OOP) principles in Python. This implementation will use three different models to make decisions based on the context.

```python
import numpy as np

class Model:
    def __init__(self):
        pass

    def predict(self, context):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def __init__(self):
        super().__init__()
        self.weights = None

    def fit(self, X, y):
        # Simple linear regression with least squares
        self.weights = np.linalg.inv(X.T @ X) @ X.T @ y

    def predict(self, context):
        return context @ self.weights

class RandomModel(Model):
    def predict(self, context):
        return np.random.rand()

class EpsilonGreedyBandit:
    def __init__(self, models, epsilon=0.1):
        self.models = models
        self.epsilon = epsilon
        self.rewards = {model: [] for model in models}
        self.contexts = []

    def select_action(self, context):
        if np.random.rand() < self.epsilon:
            action = np.random.choice(len(self.models))
        else:
            predictions = [model.predict(context) for model in self.models]
            action = np.argmax(predictions)

        reward = self.get_reward(action)
        self.update_rewards(reward, action)
        return action

    def get_reward(self, action):
        # Simulate getting a reward; replace with actual logic
        return np.random.normal(loc=self.models[action].predict(self.contexts[-1]), scale=1.0)

    def update_rewards(self, reward, action):
        self.rewards[self.models[action]].append(reward)

# Example usage
if __name__ == "__main__":
    # Create some sample contexts and true rewards
    contexts = np.array([[1, 2], [3, 4], [5, 6]])
    true_rewards = np.array([0.8, 0.9, 0.7])

    # Initialize models
    linear_model = LinearModel()
    random_model = RandomModel()
    constant_model = lambda x: 0.5

    # Fit the linear model
    linear_model.fit(contexts, true_rewards)

    # Combine all models into a list
    models = [linear_model, random_model, constant_model]

    # Initialize the bandit
    bandit = EpsilonGreedyBandit(models)

    # Run the bandit over several steps
    for _ in range(100):
        current_context = contexts[np.random.randint(0, len(contexts))]
        bandit.contexts.append(current_context)
        selected_action = bandit.select_action(current_context)
        print(f"Selected Action: {selected_action}")
```

### Explanation:
- **Model Class**: An abstract base class that defines the interface for prediction.
- **LinearModel**: A concrete subclass of `Model` that implements linear regression for predictions.
- **RandomModel**: Another concrete subclass that returns random values.
- **EpsilonGreedyBandit**: The main class that manages the selection process and updates based on rewards.
- **Example Usage**: Demonstrates how to create instances of these classes and run the bandit simulation.

This code provides a basic framework for implementing a CMAB system where multiple models can be used to inform decision-making processes. You can extend or modify it according to your specific requirements.

