using boost::asio::ip::tcp;

int main() {
    try {
        // Create an io_context object
        boost::asio::io_context io_context;

        // Create a TCP acceptor to listen on port 8888
        tcp::acceptor acceptor(io_context, tcp::endpoint(tcp::v4(), 8888));

        std::cout << "Server started and listening on port 8888..." << std::endl;

        while (true) {
            // Wait for a connection
            tcp::socket socket(io_context);
            acceptor.accept(socket);

            std::cout << "Connection accepted" << std::endl;

            // Read data from the client
            char data[1024];
            size_t length = socket.read_some(boost::asio::buffer(data), boost::asio::transfer_at_least(1));

            std::cout << "Received: " << std::string(data, length) << std::endl;

            // Optionally, send a response back to the client
            const char* response = "Hello, Client!";
            boost::asio::write(socket, boost::asio::buffer(response));
        }
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }

    return 0;
}
```

