   var height = 500;

   // Define the radius for the rounded corners
   var radius = 20; // Adjust this value to change the roundness

   // Create the rounded rectangle path
   var path = [
       [0, 0],          // Top-left corner
       [width - radius, 0], // Start of the top-right arc
       [width, 0],      // End of the top-right arc
       [width, height - radius], // Start of the bottom-right arc
       [width, height], // End of the bottom-right arc
       [radius, height], // Start of the bottom-left arc
       [0, height],     // End of the bottom-left arc
       [0, radius]      // Start of the top-left arc
   ];

   // Convert the path to a Bezier curve
   var bezierPath = [];
   for (var i = 0; i < path.length; i++) {
       if (i === 0 || i === path.length - 1) {
