                    MainDocumentPart mainPart2 = doc2.MainDocumentPart;
                    Body body2 = mainPart2.Document.Body;

                    // Add the content and glossary from the second document
                    CopyContent(mainPart2, mainPartMerged, 0, int.MaxValue); // Assuming no limit on the number of pages
                    CopyGlossary(mainPart2, mainPartMerged);
                }
            }
        }
    }

    private static void CopyContent(MainDocumentPart sourcePart, MainDocumentPart targetPart, int startPage, int endPage)
    {
        var paragraphs = sourcePart.Document.Body.Elements<Paragraph>().Skip(startPage).Take(endPage - startPage + 1);
        foreach (var paragraph in paragraphs)
        {
            targetPart.Document.Body.Append(paragraph.CloneNode(true));
        }
    }

    private static void CopyHeadersAndFooters(MainDocumentPart sourcePart, MainDocumentPart targetPart)
    {
        if (sourcePart.HeaderParts != null)
        {
            foreach (var headerPart in sourcePart.HeaderParts)
            {
                HeaderPart headerCopy = targetPart.AddNewPart<HeaderPart>();
                headerCopy.FeedData(headerPart.GetStream());
            }
        }

        if (sourcePart.FooterParts != null)
        {
            foreach (var footerPart in sourcePart.FooterParts)
            {
                FooterPart footerCopy = targetPart.AddNewPart<FooterPart>();
                footerCopy.FeedData(footerPart.GetStream());
            }
        }
    }

    private static void CopyStyles(MainDocumentPart sourcePart, MainDocumentPart targetPart)
    {
        if (sourcePart.StyleDefinitionsPart != null)
        {
            StyleDefinitionsPart styleDefinitionsCopy = targetPart.AddNewPart<StyleDefinitionsPart>();
            styleDefinitionsCopy.FeedData(sourcePart.StyleDefinitionsPart.GetStream());
        }
    }

    private static void CopyGlossary(MainDocumentPart sourcePart, MainDocumentPart targetPart)
    {
        GlossaryDocument glossary = sourcePart.Document.Descendants<GlossaryDocument>().FirstOrDefault();
        if (glossary != null)
        {
            GlossaryDocument glossaryCopy = targetPart.Document.Descendants<GlossaryDocument>().FirstOrDefault() ?? new GlossaryDocument();
            glossaryCopy.Append(glossary.CloneNode(true));
        }
    }
}
```

### Explanation:
1. **Loading Documents**: The function loads both source documents.
2. **Creating Merged Document**: A new document is created where the merged content will be stored.
3. **Copying Content**:
   - **First Document**: Copies the first 2 pages, headers, footers, and styles.
   - **Second Document**: Adds the content and glossary.
4. **Helper Methods**:
   - `CopyContent`: Copies specified paragraphs from the source to the target.
   - `CopyHeadersAndFooters`: Copies headers and footers from the source to the target.
   - `CopyStyles`: Copies styles from the source to the target.
   - `CopyGlossary`: Copies the glossary from the source to the target.

