```c
#include <stdio.h>
#include <stdlib.h>

// Simple reverb function (for demonstration purposes)
void apply_reverb(float* buffer, int length, float decay) {
    for (int i = 0; i < length; i++) {
        buffer[i] *= decay;
    }
}

// JNI function declaration
JNIEXPORT void JNICALL Java_com_example_ReverbActivity_applyReverb(JNIEnv *env, jobject obj, jfloatArray buffer, jint length, jfloat decay) {
    // Get the array elements
    jfloat* buf = (*env)->GetFloatArrayElements(env, buffer, NULL);

