use App\Models\User;
use App\Models\Favorite;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    /**
     * Add a name to the favorites list.
     *
     * @param string $name The name to add.
     */
    public function addToFavorites(string $name): void
    {
        if (auth()->check()) {
            // If the user is logged in, save to database.
            $favorite = new Favorite(['name' => $name]);
            auth()->user()->favorites()->save($favorite);
        } else {
            // If the user is a guest, save to session.
            $sessionKey = 'favorites';
            $favorites = Session::get($sessionKey, []);
            $favorites[] = $name;
            Session::put($sessionKey, array_unique($favorites));
        }
    }

    /**
     * Remove a name from the favorites list.
     *
     * @param string $name The name to remove.
     */
    public function removeFromFavorites(string $name): void
    {
        if (auth()->check()) {
            // If the user is logged in, delete from database.
            auth()->user()->favorites()->where('name', $name)->delete();
        } else {
            // If the user is a guest, remove from session.
            $sessionKey = 'favorites';
            $favorites = Session::get($sessionKey, []);
            $favorites = array_diff($favorites, [$name]);
            Session::put($sessionKey, $favorites);
        }
    }

    /**
     * Get all favorite names.
     *
     * @return array An array of favorite names.
     */
    public function getFavorites(): array
    {
        if (auth()->check()) {
            // If the user is logged in, fetch from database.
            return auth()->user()->favorites->pluck('name')->toArray();
        } else {
            // If the user is a guest, fetch from session.
            $sessionKey = 'favorites';
            return Session::get($sessionKey, []);
        }
    }
}
