```typescript
class TCPSegment {
    sourcePort: number;
    destinationPort: number;
    sequenceNumber: number;
    acknowledgmentNumber: number;
    dataOffset: number; // 4 bits, represents the size of the TCP header in 32-bit words
    reserved: number;   // 6 bits, must be zero
    flags: number;      // 6 bits, various control flags
    windowSize: number;
    checksum: number;
    urgentPointer: number;
    options: Uint8Array; // Optional fields

    constructor(data: Uint8Array) {
        this.sourcePort = (data[0] << 8) | data[1];
        this.destinationPort = (data[2] << 8) | data[3];
        this.sequenceNumber = (data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7];
        this.acknowledgmentNumber = (data[8] << 24) | (data[9] << 16) | (data[10] << 8) | data[11];
        this.dataOffset = (data[12] >> 4) & 0xF;
        this.reserved = (data[12] >> 3) & 0x7;
        this.flags = data[12] & 0x7;
        this.windowSize = (data[13] << 8) | data[14];
        this.checksum = (data[15] << 8) | data[16];
        this.urgentPointer = (data[17] << 8) | data[18];

        // Extract options if present
        const optionStartIndex = 20 + (this.dataOffset * 4);
        this.options = data.slice(optionStartIndex, data.length);
    }

    getHeaderLength(): number {
        return this.dataOffset * 4;
    }

    getData(): Uint8Array {
        const headerLength = this.getHeaderLength();
        return this.payload.slice(headerLength);
    }
}

// Example usage:
const tcpPayload: Uint8Array = new Uint8Array([
    0x00, 0x50, // Source Port
    0x00, 0x50, // Destination Port
    0x00, 0x00, 0x00, 0x01, // Sequence Number
    0x00, 0x00, 0x00, 0x00, // Acknowledgment Number
    0x50, 0x00, 0x00, 0x00, // Data Offset, Reserved, Flags, Window Size
    0x00, 0x00, // Checksum
    0x00, 0x00, // Urgent Pointer
    // Options...
]);

const tcpSegment = new TCPSegment(tcpPayload);

console.log("Source Port:", tcpSegment.sourcePort);
console.log("Destination Port:", tcpSegment.destinationPort);
console.log("Sequence Number:", tcpSegment.sequenceNumber);
console.log("Acknowledgment Number:", tcpSegment.acknowledgmentNumber);
console.log("Data Length:", tcpSegment.getData().length);
```

### Explanation:
- **TCPSegment Class**: This class parses the TCP segment from a `Uint8Array`. It extracts the various fields such as source port, destination port, sequence number, acknowledgment number, etc.
- **getHeaderLength()**: Returns the length of the TCP header in bytes.
- **getData()**: Returns the actual payload data after removing the TCP header.

This is a simplified version and does not include all possible TCP options or error handling. For a full-fledged TCP implementation, you would need to handle more complex scenarios like retransmissions, congestion control, and connection management.

