```python
import numpy as np

# Define the size of the board
ROWS = 6
COLS = 7

# Initialize the board
board = np.zeros((ROWS, COLS))

def print_board(board):
    # Print the current state of the board
    for row in range(ROWS):
        print("|", end="")
        for col in range(COLS):
            if board[row][col] == 0:
                print(" ", end="|")
            elif board[row][col] == 1:
                print("X", end="|")
            else:
                print("O", end="|")
        print()

def is_valid_location(board, col):
    # Check if it's valid to drop a piece in the given column
    return board[ROWS - 1][col] == 0

def get_next_open_row(board, col):
    # Get the next open row in the given column
    for r in range(ROWS):
        if board[r][col] == 0:
            return r

def drop_piece(board, row, col, player):
    # Drop a piece in the given row and column for the given player
    board[row][col] = player

def winning_move(board, player):
    # Check for a winning move for the given player
    # Check horizontal locations for win
    for c in range(COLS - 3):
        for r in range(ROWS):
            if board[r][c] == player and board[r][c + 1] == player and board[r][c + 2] == player and board[r][c + 3] == player:
                return True

    # Check vertical locations for win
    for c in range(COLS):
        for r in range(ROWS - 3):
            if board[r][c] == player and board[r + 1][c] == player and board[r + 2][c] == player and board[r + 3][c] == player:
                return True

    # Check positively sloped diagonals
    for c in range(COLS - 3):
        for r in range(ROWS - 3):
            if board[r][c] == player and board[r + 1][c + 1] == player and board[r + 2][c + 2] == player and board[r + 3][c + 3] == player:
                return True

    # Check negatively sloped diagonals
    for c in range(COLS - 3):
        for r in range(3, ROWS):
            if board[r][c] == player and board[r - 1][c + 1] == player and board[r - 2][c + 2] == player and board[r - 3][c + 3] == player:
                return True

    return False

def main():
    turn = 0
    game_over = False

    while not game_over:
        # Ask for Player 1 Input
        if turn % 2 == 0:
            col = int(input("Player 1 Make your Selection (0-6): "))
            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 1)

                if winning_move(board, 1):
                    print_board(board)
                    print("PLAYER 1 WINS!!")
                    game_over = True

        # Ask for Player 2 Input
        else:
            col = int(input("Player 2 Make your Selection (0-6): "))
            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 2)

                if winning_move(board, 2):
                    print_board(board)
                    print("PLAYER 2 WINS!!")
                    game_over = True

        print_board(board)

        turn += 1

if __name__ == "__main__":
    main()
```

This code defines a simple Connect-4 game where two players take turns dropping their pieces into columns on a 6x7 grid. The game checks for a winning move after each turn and ends when one player wins or all spaces on the board are filled.

